// Generates migrations/0003_app_details.sql from scripts/app-info.cjs.
const fs = require('fs');
const path = require('path');
const info = require('./app-info.cjs');
const q = s => "'" + String(s).replace(/'/g, "''") + "'";
const out = [
  '-- Generated by scripts/make-details.cjs',
  "ALTER TABLE apps ADD COLUMN description TEXT NOT NULL DEFAULT '';",
  "ALTER TABLE apps ADD COLUMN price TEXT NOT NULL DEFAULT 'free' CHECK (price IN ('free','freemium','paid'));",
  'ALTER TABLE apps ADD COLUMN open_source INTEGER NOT NULL DEFAULT 0;',
  // Trawlr goes directly above Everything in Utilities.
  `INSERT INTO apps (key, name, category, source, url, url_pattern, args, note, homepage, sort)
  VALUES ('trawlr', 'Trawlr', 'Utilities', 'direct',
    'https://api.github.com/repos/SamuelCGilbert/trawlr/releases/latest',
    ${q('https://github[.]com/SamuelCGilbert/trawlr/releases/download/[^"]+-windows-x64-setup[.]exe')},
    '/VERYSILENT /SUPPRESSMSGBOXES /NORESTART /SP-', 'Instant file search with an always-current index',
    'https://github.com/SamuelCGilbert/trawlr',
    (SELECT sort - 5 FROM apps WHERE key = 'everything'));`,
];
for (const [key, [price, oss, desc]] of Object.entries(info)) {
  out.push(`UPDATE apps SET description = ${q(desc)}, price = ${q(price)}, open_source = ${oss} WHERE key = ${q(key)};`);
}
fs.writeFileSync(path.join(__dirname, '../migrations/0003_app_details.sql'), out.join('\n') + '\n');
console.log(Object.keys(info).length, 'apps described');
